// 30-tap FIR, TRANSPOSED direct form: one multiply + one add per stage, so a
// short per-stage PIPELINE (the rest of the path is independent of the
// register-to-register delay) -> short register-to-register path + wide per-
// stage (short PIPELINE) => high Fmax. Same function as the direct form (equivalent
// up to a fixed extra latency).
module fir30_v5_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [23:0] a0, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14, a15, a16, a17, a18, a19, a20, a21, a22, a23, a24, a25, a26, a27, a28, a29;
    wire [23:0] y_pipelined = 44 * a0 + 37 * a1 + 25 * a2 + 24 * a3 + 58 * a4 + 4 * a5 + 24 * a6 + 58 * a7 + 23 * a8 + 46 * a9 + 25 * a10 + 35 * a11 + 40 * a12 + 8 * a13 + 33 * a14 + 12 * a15 + 18 * a16 + 9 * a17 + 63 * a18 + 4 * a19 + 1 * a20 + 45 * a21 + 21 * a22 + 43 * a23 + 25 * a24 + 33 * a25 + 4 * a26 + 57 * a27 + 44 * a28 + 11 * a29;
    always @(posedge clk) begin
        if (!rst_n) begin
            a0 <= 24'd0; a1 <= 24'd0; a2 <= 24'd0; a3 <= 24'd0; a4 <= 24'd0; a5 <= 24'd0; a6 <= 24'd0; a7 <= 24'd0; a8 <= 24'd0; a9 <= 24'd0; a10 <= 24'd0; a11 <= 24'd0; a12 <= 24'd0; a13 <= 24'd0; a14 <= 24'd0; a15 <= 24'd0; a16 <= 24'd0; a17 <= 24'd0; a18 <= 24'd0; a19 <= 24'd0; a20 <= 24'd0; a21 <= 24'd0; a22 <= 24'd0; a23 <= 24'd0; a24 <= 24'd0; a25 <= 24'd0; a26 <= 24'd0; a27 <= 24'd0; a28 <= 24'd0; a29 <= 24'd0; y <= 16'd0;
        end else begin
            a0 <= 8'd1 * x;
            a1 <= a0 + 8'd1 * x;
            a2 <= a1 + 8'd1 * x;
            a3 <= a2 + 8'd1 * x;
            a4 <= a3 + 8'd1 * x;
            a5 <= a4 + 8'd1 * x;
            a6 <= a5 + 8'd1 * x;
            a7 <= a6 + 8'd1 * x;
            a8 <= a7 + 8'd1 * x;
            a9 <= a8 + 8'd1 * x;
            a10 <= a9 + 8'd1 * x;
            a11 <= a10 + 8'd1 * x;
            a12 <= a11 + 8'd1 * x;
            a13 <= a12 + 8'd1 * x;
            a14 <= a13 + 8'd1 * x;
            a15 <= a14 + 8'd1 * x;
            a16 <= a15 + 8'd1 * x;
            a17 <= a16 + 8'd1 * x;
            a18 <= a17 + 8'd1 * x;
            a19 <= a18 + 8'd1 * x;
            a20 <= a19 + 8'd1 * x;
            a21 <= a20 + 8'd1 * x;
            a22 <= a21 + 8'd1 * x;
            a23 <= a22 + 8'd1 * x;
            a24 <= a23 + 8'd1 * x;
            a25 <= a24 + 8'd1 * x;
            a26 <= a25 + 8'd1 * x;
            a27 <= a26 + 8'd1 * x;
            a28 <= a27 + 8'd1 * x;
            a29 <= a28 + 8'd1 * x;
            y <= y_pipelined[15:0];
        end
    end
endmodule
